export function phosphorIconSvg(name, { size = 20, className = '' } = {}) {
  const inner = PHOSPHOR_ICONS[name];
  if (!inner) return '';
  const cls = className ? ` class="${className}"` : '';
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" width="${size}" height="${size}" fill="currentColor" aria-hidden="true" focusable="false"${cls}>${inner}</svg>`;
}
